<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST')try{$a=FileService::save($_FILES['file']??null,'documents',['pdf'=>['application/pdf'],'jpg'=>['image/jpeg'],'jpeg'=>['image/jpeg'],'png'=>['image/png'],'doc'=>['application/msword'],'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document']]);db()->prepare('INSERT INTO documents(owner_user_id,title,category,file_path,mime_type,file_size) VALUES(?,?,?,?,?,?)')->execute([actor_id(),$_POST['title'],$_POST['category'],$a['path'],$a['mime'],$a['size']]);$_SESSION['flash']=['success','Document uploaded'];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('documents.php');$q=db()->prepare('SELECT * FROM documents WHERE owner_user_id=? ORDER BY id DESC');$q->execute([actor_id()]);page_top('My Secure Documents');flash();?><div class="card p-4 mb-3"><form method="post" enctype="multipart/form-data" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-5"><input name="title" class="form-control" placeholder="Title" required></div><div class="col-md-3"><input name="category" class="form-control" placeholder="Category" required></div><div class="col-md-4"><input type="file" name="file" class="form-control" required></div><button class="btn btn-primary col-md-2">Upload</button></form></div><div class="card p-3"><table class="table"><tr><th>Title</th><th>Category</th><th>Verification</th><th>Uploaded</th></tr><?php foreach($q as $d):?><tr><td><?=e($d['title'])?></td><td><?=e($d['category'])?></td><td><?=e($d['verification_status'])?></td><td><?=e($d['created_at'])?></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>